package com.staging.sg.fraud.gateway.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.staging.sg.fraud.gateway.api.IsoFraudApi.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.*;
class Iso8583FraudMapperTest{private final Iso8583FraudMapper mapper=new Iso8583FraudMapper(62,63,48);
 @Test void mapsTokenizedRequestAndPreservesAuthorizationResponse(){Map<String,String>f=new LinkedHashMap<>();f.put("4","000000001000");f.put("18","5411");f.put("22","010");f.put("37","REF000000001");f.put("39","00");f.put("49","504");f.put("62","tok_network_001");var req=new IsoMessageRequest("0200",f);var canonical=mapper.toCanonical(req);assertThat(canonical).containsEntry("currency","MAD").containsEntry("cardPresent",false);var score=new ObjectMapper().createObjectNode().put("score",720).put("recommendedAction","REVIEW_IMMEDIATELY").put("enforcedAction","NO_BLOCK_ALERT_ONLY");var out=mapper.response(req,score);assertThat(out.mti()).isEqualTo("0210");assertThat(out.fields()).containsEntry("39","00");assertThat(out.fields().get("63")).contains("FRAUD_SCORE=720");}
 @Test void rejectsPanAndMissingToken(){assertThatThrownBy(()->mapper.toCanonical(new IsoMessageRequest("0200",Map.of("2","4111111111111111")))).isInstanceOf(IllegalArgumentException.class).hasMessageContaining("PAN");}}
